#include "AssemblyGraph.h"
#include "AssemblyRevolute.h"
#include "JointOrigin.h"
#include "LocalOccurrences.h"
#include "CadDocument.h"
#include <BRepAdaptor_Curve.hxx>
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cmath>
#include <iostream>
