namespace {
void check(bool v,const char* t){if(!v)throw std::runtime_error(t);}
void near(double a,double b,const char* t,double tolerance=1e-5){check(std::abs(a-b)<tolerance,t);}
void commit(CadDocument& d,const QJsonObject& a){const auto e=d.commit(a,"Cylindrical core");check(e.isEmpty(),qPrintable(e));}
QString definition(const QJsonObject& a,const QString& name){for(const auto& v:a["components"].toArray())if(v.toObject()["name"]==name)return v.toObject()["id"].toString();return {};}
QString occurrence(const QJsonObject& a,const QString& definition){for(const auto& v:a["occurrences"].toArray())if(v.toObject()["definitionId"]==definition)return v.toObject()["id"].toString();return {};}
const EvaluatedBody& body(const std::vector<EvaluatedBody>& bodies,const QString& owner){for(const auto& b:bodies)if(b.ownerId==owner)return b;throw std::runtime_error("Fixture leaf body unavailable");}
QJsonObject origin(const EvaluatedBody& b,bool tube,double x=90,double z=-1){QJsonObject selected;double lowest=1e10;for(const auto& e:b.solidEdges)if(!e.edge.IsNull()){BRepAdaptor_Curve c(e.edge);if(c.GetType()!=GeomAbs_Circle||std::abs(std::abs(c.LastParameter()-c.FirstParameter())-2*std::acos(-1.0))>1e-6)continue;auto v=c.Circle();auto p=v.Location();if(std::abs(p.X()-x)>1e-5||std::abs(tube?v.Axis().Direction().Z():v.Axis().Direction().Y())<1-1e-6)continue;if(tube&&std::abs(p.Y())>1e-5)continue;if(z>=0&&std::abs(p.Z()-z)>1e-5)continue;if(p.Z()<lowest){lowest=p.Z();selected={{"bodyId",b.bodyId},{"edgeId",e.edgeId}};}}return selected;}
QJsonObject joint(const QJsonObject& state,const QString& id){for(const auto& v:state["joints"].toArray())if(v.toObject()["id"]==id)return v.toObject();throw std::runtime_error("Joint unavailable");}
QJsonArray leafPose(const QJsonObject& s,const QString& id){for(const auto& v:s["occurrences"].toArray())if(v.toObject()["occurrenceId"]==id)return v.toObject()["worldPose"].toArray();return {};}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 check(argc==2,"Pass actual piston fixture");CadDocument d;check(d.open(QString::fromLocal8Bit(argv[1])).isEmpty(),"Open fixture");const auto a=d.authored();const auto lower=definition(a,"Lower arm"),inner=definition(a,"Inner piston"),outer=definition(a,"Outer piston");const auto l=occurrence(a,lower),i=occurrence(a,inner),o=occurrence(a,outer);const auto& lowerBody=body(d.bodies(),lower);QJsonObject bore;
 for(const auto& candidate:JointOrigin::cylindricalCandidates(lowerBody)){const auto p=candidate["centerMm"].toArray();if(std::abs(p[0].toDouble()-90)<1e-5&&std::abs(p[2].toDouble())<1e-5&&std::abs(candidate["radiusMm"].toDouble()-4.5)<1e-5)bore=candidate;}
 check(!bore.isEmpty(),"Actual finite lower mounting bore has two named rims");const auto reference=bore["position"].toObject();const auto resolved=JointOrigin::resolve(lowerBody,reference);const auto actualPick=JointOrigin::cylindricalFaceCandidate(lowerBody,resolved.face);check(actualPick["position"]==reference,"Exact picked face maps retained rim pair");auto positioned=LocalOccurrences::worldBodies(a,d.evaluation());const auto& worldLower=body(positioned,lower);const auto worldResolved=JointOrigin::resolve(worldLower,reference);check(JointOrigin::cylindricalFaceCandidate(worldLower,worldResolved.face)["position"].toObject()["occurrenceId"]==l,"Exact world instance pick retains occurrence");
 auto position=reference;position["occurrenceId"]=l;commit(d,AssemblyGraph::revoluteCandidate(a,d.evaluation(),{{"component1OccurrenceId",i},{"component2OccurrenceId",l},{"position",position}}));const auto retained=d.authored();const auto row=retained["joints"].toArray()[0].toObject();check(row["position"]==reference&&row["movingPosition"].toObject().contains("rimEdgeIds"),"Both exact bore references retained");const auto id=row["id"].toString();near(joint(d.assemblyState(),id)["originFrameWorld"].toArray()[7].toDouble(),resolved.center.Y(),"Bore axis midpoint origin");
 QString parent;for(const auto& v:a["components"].toArray())if(v.toObject()["name"]=="Piston subassembly")parent=occurrence(a,v.toObject()["id"].toString());const auto copied=CadDocument::copyOccurrenceCandidate(a,parent,{{"axis","Z"},{"angleDeg",0},{"translationMm",QJsonArray{-180,0,0}}});const auto ci=copied["occurrenceMap"].toObject()[i].toString();bool pickedCopy=false;for(const auto& b:LocalOccurrences::worldBodies(copied["authored"].toObject(),d.evaluation()))if(b.occurrenceId==ci){const auto pair=row["movingPosition"].toObject();const auto exact=JointOrigin::resolve(b,pair);const auto pick=JointOrigin::cylindricalFaceCandidate(b,exact.face);check(pick["position"].toObject()["occurrenceId"]==ci,"Translated copy exact face keeps distinct occurrence");near(pick["centerMm"].toArray()[0].toDouble(),-90,"Translated exact cylinder midpoint follows world placement");bool rejectedOriginal=false;try{JointOrigin::cylindricalFaceCandidate(b,JointOrigin::resolve(body(d.bodies(),inner),pair).face);}catch(const std::exception&){rejectedOriginal=true;}check(rejectedOriginal,"Unplaced source face cannot substitute for exact copied face");pickedCopy=true;}check(pickedCopy,"Actual translated copy inference checked");
 const auto end=origin(body(d.bodies(),outer),true);const auto endCandidate=JointOrigin::circleCandidate(body(d.bodies(),outer),end["edgeId"].toString());check(endCandidate["snapKind"]=="circleCenter","End circle uses center snap");const auto endCenter=endCandidate["centerMm"].toArray();near(endCenter[0].toDouble(),90,"Circle center lies on axis X");near(endCenter[1].toDouble(),0,"Circle center lies on axis Y");
 auto edited=retained;auto fs=edited["features"].toArray();for(int n=0;n<fs.size();++n){auto f=fs[n].toObject();if(f["name"]=="Lower arm"&&f["type"]=="extrude"){auto parameters=f["parameters"].toObject();parameters["distanceMm"]=parameters["distanceMm"].toDouble()+4;f["parameters"]=parameters;fs[n]=f;}}edited["features"]=fs;commit(d,edited);check(d.authored()["joints"]==retained["joints"],"Source edit retains rim pair IDs");near(joint(d.assemblyState(),id)["originFrameWorld"].toArray()[7].toDouble(),resolved.center.Y()-2,"Source width updates midpoint by half reach change");check(joint(d.assemblyState(),id)["maxOriginErrorMm"].toDouble()<1e-5,"Original relation satisfied after midpoint edit");d.history().undo();check(d.authored()==retained,"Source edit undo");d.history().redo();check(d.authored()==edited,"Source edit redo");QTemporaryDir temp;const auto path=temp.filePath("inferred-origin.alloy");check(d.save(path).isEmpty(),"Save inferred origin");CadDocument reopened;check(reopened.open(path).isEmpty()&&reopened.authored()==edited,"Exact inferred origin reopen");near(joint(reopened.assemblyState(),id)["originFrameWorld"].toArray()[7].toDouble(),resolved.center.Y()-2,"Reopened midpoint resolves current source");
 auto bad=edited;auto rows=bad["joints"].toArray();auto broken=rows[0].toObject();auto missing=reference;auto ids=missing["rimEdgeIds"].toArray();ids[1]=CadDocument::newId();missing["rimEdgeIds"]=ids;broken["position"]=missing;rows[0]=broken;bad["joints"]=rows;const auto revision=reopened.revision();check(!reopened.commit(bad,"Broken midpoint").isEmpty()&&reopened.authored()==edited&&reopened.revision()==revision,"Missing rim pair refuses atomically");
 bool refused=false;auto corrupt=lowerBody;for(auto& edge:corrupt.solidEdges)if(edge.edgeId==reference["rimEdgeIds"].toArray()[0])edge.edge.Nullify();try{JointOrigin::resolve(corrupt,reference);}catch(const std::exception&){refused=true;}check(refused,"Unavailable retained rim refuses");auto wrong=reference;wrong["rimEdgeIds"]=QJsonArray{end["edgeId"],reference["rimEdgeIds"].toArray()[0]};refused=false;try{JointOrigin::resolve(lowerBody,wrong);}catch(const std::exception&){refused=true;}check(refused,"Unrelated rim pair refuses");
 CadDocument complete;check(complete.open(QString::fromLocal8Bit(argv[1])).isEmpty(),"Fresh full inferred-origin fixture");const auto upper=definition(a,"Upper arm"),u=occurrence(a,upper);auto addBore=[&](QString moving,QString fixed,QString owner,double x,double z){QJsonObject selected;for(const auto& candidate:JointOrigin::cylindricalCandidates(body(complete.bodies(),owner))){const auto point=candidate["centerMm"].toArray();if(std::abs(point[0].toDouble()-x)<1e-5&&std::abs(point[2].toDouble()-z)<1e-5&&std::abs(candidate["radiusMm"].toDouble()-4.5)<1e-5)selected=candidate["position"].toObject();}check(!selected.isEmpty(),"Full fixture exact retained bore");selected["occurrenceId"]=fixed;commit(complete,AssemblyGraph::revoluteCandidate(complete.authored(),complete.evaluation(),{{"component1OccurrenceId",moving},{"component2OccurrenceId",fixed},{"position",selected}}));};addBore(u,l,lower,0,80);const auto drive=complete.authored()["joints"].toArray()[0].toObject()["id"].toString();commit(complete,AssemblyGraph::cylindricalCandidate(complete.authored(),complete.evaluation(),{{"component1OccurrenceId",i},{"component2OccurrenceId",o},{"position",end}}));addBore(i,l,lower,90,0);addBore(o,u,upper,90,180);commit(complete,CadDocument::pinOccurrenceCandidate(complete.authored(),l));const auto full=AssemblyGraph::inspect(complete.authored(),complete.evaluation(),{{"jointId",drive},{"angleDeg",15}});for(const auto& v:full["joints"].toArray())check(v.toObject()["maxOriginErrorMm"].toDouble()<1e-5&&v.toObject()["maxAxisErrorRadians"].toDouble()<1e-6,"Complete bore-inferred source relations remain satisfied");near(joint(full,drive)["coordinateDeg"].toDouble(),15,"Complete inferred-origin driver");
 std::cout<<"ORIGIN_OK exactface/midpoint/edgecenter/occurrence/sourcewidth/history/reopen/refusal\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
